import random

def get_user_move():
    """Get user's move as input."""
    while True:
        move = input("Enter 'rock', 'paper', or 'scissors': ").lower()
        if move in ['rock', 'paper', 'scissors']:
            return move
        else:
            print("Invalid input. Please enter 'rock', 'paper', or 'scissors'.")

def get_computer_move():
    """Get computer's move randomly."""
    return random.choice(['rock', 'paper', 'scissors'])

def play_round():
    """Play one round of Rock, Paper, Scissors."""
    user_move = get_user_move()
    computer_move = get_computer_move()

    print(f"You chose {user_move.capitalize()}.")
    print(f"Computer chose {computer_move.capitalize()}.")

    if user_move == computer_move:
        print("It's a tie!")
    elif (user_move == 'rock' and computer_move == 'scissors') or \
         (user_move == 'paper' and computer_move == 'rock') or \
         (user_move == 'scissors' and computer_move == 'paper'):
        print(f"{user_move.capitalize()} covers {computer_move.capitalize()}. You win!")
    else:
        print(f"{computer_move.capitalize()} cuts {user_move.capitalize()}. Computer wins!")

def play_game():
    """Play multiple rounds of Rock, Paper, Scissors."""
    num_rounds = int(input("Enter the number of rounds to play: "))

    for _ in range(num_rounds):
        play_round()

    print("\nGame over. Thanks for playing!")

if __name__ == "__main__":
    play_game()
```

This program defines three functions: `get_user_move()`, `get_computer_move()`, and `play_round()`. The `play_game()` function calls `play_round()` multiple times based on user input. The game continues until the user enters a valid number of rounds to play.
